GIFU.FIGINDEX = [{"p":"index","n":1,"c":{"en":"Gifu as a schematic map — not to scale.","ja":"岐阜県の模式図（縮尺は正確ではない）。","zh":"岐阜縣示意圖（非按比例）。"}},{"p":"start","n":1,"c":{"en":"Five routes through the book.","ja":"本書の五つの道筋。それぞれ主題の枠組みを示す頁から始まり、主題が現在と出会う頁で終わる。","zh":"穿越本書的五條路線。每條從勾勒主題輪廓的頁面開始，在主題與當代相遇之處結束。"}},{"p":"spirit","n":1,"c":{"en":"From land to thing. Each row runs from a resource the prefecture supplies, through the verb that transforms it, to wh…","ja":"土地からものへ。各行は、県が与える資源から、それを変える動詞を経て、作られるものとその場所へと進む。","zh":"從土地到器物。每一行從本縣供給的資源出發，經過轉化它的動詞，到達所造之物及其產地。"}},{"p":"names","n":1,"c":{"en":"The two characters. 岐 is the first character of Qishan (岐山), the mountain from which King Wen of Zhou began the rise…","ja":"二つの文字。「岐」は周の文王が興った山、岐山の岐。","zh":"兩個字。「岐」是岐山的岐——周文王由此興起；「阜」意為丘陵、土山，是孔子故里曲阜的阜。"}},{"p":"provinces","n":1,"c":{"en":"Land against people, 2025.","ja":"土地と人口（2025年）。","zh":"土地與人口（2025 年）。"}},{"p":"landform","n":1,"c":{"en":"A schematic section from the Northern Alps to Ise Bay.","ja":"北アルプスから伊勢湾までの模式断面。","zh":"從北阿爾卑斯到伊勢灣的示意剖面。"}},{"p":"rivers","n":1,"c":{"en":"Two sides of a divide.","ja":"分水嶺の両側。郡上市ひるがの（標高約875m）では、一筋の流れが二つに分かれ、一方は庄川となって北の日本海へ…","zh":"分水嶺兩側。郡上市蛭野（ひるがの，海拔約 875 公尺）的一道溪流在此一分為二：一支成為庄川，北流入日本海；另…"}},{"p":"forests","n":1,"c":{"en":"What the forest is made of.","ja":"森が何からなるか。上：森林全体の所有——国有林が約五分の一、民有林が約五分の四。","zh":"森林由什麼構成。上：全部森林的所有權——國有林約五分之一，民有林約五分之四。"}},{"p":"mountains","n":1,"c":{"en":"The four peaks of this page, as heights.","ja":"本頁の四つの山を高さで並べる。","zh":"本頁四座山峰的高度比較。御嶽山與乘鞍岳是火山；位於石川縣界的白山也是火山；笠岳則是飛驒山脈中的山峰。"}},{"p":"wildlife","n":1,"c":{"en":"Life by altitude — a qualitative sketch.","ja":"標高と生きもの——定性的な略図。","zh":"依海拔分布的生物——定性示意。"}},{"p":"climate","n":1,"c":{"en":"The working year. Typical seasons for the activities described in this book; exact dates vary by year, by town and by…","ja":"仕事の一年。本書で扱う営みの、おおよその季節。","zh":"一年的工作。本書所述各項活動的大致季節；確切日期因年份、城鎮與製作者而異。"}},{"p":"history","n":1,"c":{"en":"Gifu's history on one line.","ja":"岐阜の歴史を一本の線で。帯は日本の一般的な時代区分、上の印は本書のこの部で扱う美濃・飛騨の出来事である。","zh":"一條線上的岐阜歷史。色帶為日本慣用的時代分期，上方標記為本書這一部分所談的美濃與飛驒事件。"}},{"p":"ancient","n":1,"c":{"en":"What a province owed under the eighth-century codes, and what Hida owed instead.","ja":"八世紀の律令で国が負った税と、飛騨がその代わりに負ったもの。","zh":"八世紀律令下一般國所負擔的租稅，以及飛驒改為負擔的內容。"}},{"p":"nobunaga","n":1,"c":{"en":"Nobunaga's Gifu in section.","ja":"信長の岐阜を断面で見る。金華山（約329m）山頂の城、西麓の石垣の庭と金箔瓦をもつ館、長良川の川湊を持つ城下町…","zh":"剖面中的信長岐阜。金華山（約 329 公尺）山頂的城、西麓擁有石垣庭園與金箔瓦的宮殿、臨長良川河港的城下町，以…"}},{"p":"sekigahara","n":1,"c":{"en":"The field on the morning of 15 September 1600, schematic.","ja":"1600年9月15日朝の戦場（模式図）。","zh":"1600 年 9 月 15 日早晨的戰場（示意圖）。"}},{"p":"chisui","n":1,"c":{"en":"Before and after, schematic.","ja":"前と後（模式図）。左：明治の工事以前、下流の平野で三川は流路を共有し、互いにつながり、村々は輪中の堤で身を守っ…","zh":"改修前後對照（示意圖）。左：明治工程以前，三川在下游平原共用河道、彼此相連，村落以輪中堤防自保。"}},{"p":"modern","n":1,"c":{"en":"Population of Gifu Prefecture, schematic.","ja":"岐阜県の人口（模式図）。人口は二十世紀を通じて増え、2000年の国勢調査で約211万人の頂点に達し、2018年…","zh":"岐阜縣人口（示意圖）。人口在二十世紀持續增長，於 2000 年國勢調查達到約 211 萬人的高峰，2018 年…"}},{"p":"festivals","n":1,"c":{"en":"A Takayama festival float (yatai), schematic elevation.","ja":"高山祭の屋台（模式的な立面図）。","zh":"高山祭屋台（示意立面圖）。"}},{"p":"ukai","n":1,"c":{"en":"A cormorant boat at work, schematic.","ja":"漁をする鵜舟（模式図）。鵜匠は舳先近く、篝のそばに立ち、手縄で十〜十二羽の鵜を操る。","zh":"作業中的鵜舟（示意圖）。鵜匠站在船首附近的篝籃旁，以繩牽引十到十二隻鸕鶿；每隻鳥頸根部繫著的「首結」，使牠無法…"}},{"p":"shirakawago","n":1,"c":{"en":"A gasshō house in section, schematic.","ja":"合掌造りの家の断面（模式図）。","zh":"合掌造房屋剖面（示意圖）。"}},{"p":"towns","n":1,"c":{"en":"Three streets, schematic elevations.","ja":"三つの町並み（模式立面図）。","zh":"三種街景（示意立面圖）。在高山，商家低矮、色深、立著格子，深簷之下是低矮的二樓，街邊溝渠流著水；酒藏簷下掛著杉…"}},{"p":"roads","n":1,"c":{"en":"The Nakasendō in Gifu, schematic, from Magome in the east to Imasu on the border of Ōmi.","ja":"岐阜県内の中山道（模式図）。","zh":"岐阜縣境內的中山道（示意圖），東起馬籠，西至與近江交界的今須。"}},{"p":"food","n":1,"c":{"en":"A year of Gifu food, schematic.","ja":"岐阜の食の一年（模式図）。","zh":"岐阜飲食的一年（示意圖）。"}},{"p":"kabuki","n":1,"c":{"en":"A village playhouse in plan, schematic, modelled on the larger Meiji-era houses such as the Kashimo Meiji-za.","ja":"芝居小屋の平面（模式図）。","zh":"芝居小屋平面圖（示意），以かしも明治座等明治時期的大型戲棚為範本。"}},{"p":"wood","n":1,"c":{"en":"Which wood, for what: the main timbers of Gifu, where they grow and what is made from them.","ja":"どの木を、何に。岐阜の主な木材と、その産地、そこから作られるもの。","zh":"何種木材，做什麼用：岐阜的主要木材、產地與用途。"}},{"p":"hinoki","n":1,"c":{"en":"Left: how hinoki's strength changes after felling, after the wood scientist Obara Jirō — it grows stiffer and harder…","ja":"左：伐採後の檜の強さの変化（木材学者・小原二郎による）。","zh":"左：檜木伐採後強度的變化（依木材學者小原二郎）——約兩百年間剛性與硬度持續增加，之後衰減極其緩慢，使得千年以上…"}},{"p":"logging","n":1,"c":{"en":"The life of a conifer plantation, schematic.","ja":"人工林の一生（模式図）。苗木を密に植え、はじめの数年は毎夏下刈りをし、つるや不要な木を除き、節のない材をとるた…","zh":"針葉樹人工林的一生（示意圖）。"}},{"p":"rafting","n":1,"c":{"en":"How timber reached the sea, schematic.","ja":"木はどう海へ出たか（模式図）。","zh":"木材如何抵達大海（示意圖）。"}},{"p":"takumi","n":1,"c":{"en":"Tax paid in carpenters, schematic.","ja":"大工で納める税（模式図）。","zh":"以木匠納稅（示意圖）。依《養老令》，其他各國向都城送交稻米、布匹與地方產物；飛驒則免除庸與調，改由每個五十戶組…"}},{"p":"joinery","n":1,"c":{"en":"Four ways to join wood, schematic.","ja":"木の四つの組み方（模式図）。","zh":"四種接合木材的方式（示意圖）。"}},{"p":"furniture","n":1,"c":{"en":"Bending wood, schematic.","ja":"木を曲げる（模式図）。木目のまっすぐな橅の材を丸く削り、蒸気で柔らかくし、外側の面に鋼の帯金を沿わせて型に巻き…","zh":"彎曲木材（示意圖）。紋理筆直的山毛櫸坯料先車圓，再以蒸氣軟化，然後在外側面夾上一條鋼帶，繞著模具彎曲——如此木…"}},{"p":"carving","n":1,"c":{"en":"Left: a log of Japanese yew in section.","ja":"左：イチイの丸太の断面。一位一刀彫の彫師は、濃い赤の心材（赤太）と淡い辺材（白太）が望むところ——白い顔、赤い…","zh":"左：日本紫杉原木的剖面。一位一刀雕的雕刻師會規劃每件作品，讓深紅色的心材與淺色的邊材落在想要的位置——白色的臉…"}},{"p":"enku","n":1,"c":{"en":"Where Enkū's figures are, and when he made them.","ja":"円空仏はどこにあり、いつ彫られたか。","zh":"圓空佛像的分布，以及製作年代。"}},{"p":"everyday","n":1,"c":{"en":"The masu family, schematic, seen from above and drawn to scale by volume: one gō is about 180 ml, the usual serving o…","ja":"枡の一族（模式図）。上から見て、容積に合わせた縮尺で描く。","zh":"枡的家族（示意圖），俯視，並依容積按比例繪製：一「合」約 180 毫升，是一杯清酒的常見份量；十合為一「升」，…"}},{"p":"architecture","n":1,"c":{"en":"Seven centuries of building in wood in Gifu, a selection.","ja":"岐阜の木の建築七百年（抜粋）。","zh":"岐阜木造建築七百年（選錄）。"}},{"p":"guitars","n":1,"c":{"en":"A steel-string acoustic guitar and its woods, schematic.","ja":"スチール弦のアコースティックギターとその材（模式図）。","zh":"鋼弦木吉他及其用材（示意圖）。"}},{"p":"metal","n":1,"c":{"en":"Super-Kamiokande in the old Kamioka mine, schematic section.","ja":"旧神岡鉱山のスーパーカミオカンデ（模式断面図）。","zh":"舊神岡礦山中的超級神岡探測器（示意剖面圖）。"}},{"p":"seki","n":1,"c":{"en":"Seven centuries of blades at Seki, schematic.","ja":"関の刃物七百年（模式図）。","zh":"關的刀刃七百年（示意圖）。"}},{"p":"sword","n":1,"c":{"en":"How to read a Mino blade, schematic.","ja":"美濃の刀の見方（模式図）。","zh":"如何觀賞美濃刀（示意圖）。"}},{"p":"forging","n":1,"c":{"en":"From steel to sword, schematic.","ja":"鋼から刀へ（模式図）。左：一般的な甲伏せの造りでは、炭素の少ない柔らかい心鉄を、炭素の多い硬い皮鉄で包む。","zh":"從鋼到刀（示意圖）。左：常見的「甲伏」構造，是以含碳量較高、堅硬的「皮鐵」包覆含碳量較低、較柔韌的「心鐵」，使…"}},{"p":"fittings","n":1,"c":{"en":"A sword and its mounting, taken apart, schematic.","ja":"刀とその拵を分解したところ（模式図）。","zh":"拆開的刀與刀裝（示意圖）。"}},{"p":"cutlery","n":1,"c":{"en":"How a factory kitchen knife is made, schematic.","ja":"工場の包丁ができるまで（模式図）。","zh":"工廠菜刀的製作流程（示意圖）。"}},{"p":"knives","n":1,"c":{"en":"Seven common Japanese kitchen knives, schematic, drawn to about the same scale, with their edge sections.","ja":"よく使われる七つの包丁（模式図）。","zh":"七種常見的日本菜刀（示意圖），大致以相同比例繪製，並附刃口剖面。"}},{"p":"washi","n":1,"c":{"en":"How Mino paper is made by hand, schematic.","ja":"美濃紙の手漉き（模式図）。","zh":"美濃紙的手工抄造（示意圖）。"}},{"p":"minoyaki","n":1,"c":{"en":"Left: the four great glazes of Momoyama Mino, schematic swatches.","ja":"左：桃山の美濃の四つの代表的な釉（模式的な色見本）。","zh":"左：桃山時代美濃四大代表釉色（示意色樣）。"}},{"p":"lanterns","n":1,"c":{"en":"Three things of paper and bamboo, schematic.","ja":"紙と竹の三つの品（模式図）。","zh":"三件紙與竹的器物（示意圖）。"}},{"p":"textiles","n":1,"c":{"en":"Two Gifu textiles, schematic.","ja":"岐阜の二つの布（模式図）。","zh":"岐阜的兩種布藝（示意圖）。"}},{"p":"register","n":1,"c":{"en":"Where the crafts of Gifu are made, schematic, by the prefecture's five regions.","ja":"岐阜の工芸はどこで作られているか（模式図）。","zh":"岐阜工藝的產地（示意圖），依縣內五大圈域劃分。"}},{"p":"sake","n":1,"c":{"en":"A brewing year, schematic.","ja":"酒造りの一年（模式図）。米は秋に収穫され、造りは寒い月々に行われる。","zh":"釀酒的一年（示意圖）。稻米在秋季收成，釀造則在寒冷的月份進行，低溫讓漫長的發酵保持潔淨。"}},{"p":"sakeland","n":1,"c":{"en":"Polishing rice, schematic.","ja":"米を磨く（模式図）。蔵人は、酒を粗くしかねないたんぱく質・脂質・ミネラルを含む米粒の外側を削り、でんぷんの多い…","zh":"精米（示意圖）。釀酒師把米粒外層磨去——那裡含有會使酒味粗糙的蛋白質、脂肪與礦物質——以取得富含澱粉的中心。"}},{"p":"hidasake","n":1,"c":{"en":"Inside a brewery, schematic.","ja":"酒蔵のなか（模式図）。磨いた米を洗い、浸し、蒸す。","zh":"酒藏內部（示意圖）。精磨後的米經洗米、浸米與蒸米；一部分在溫暖的麴室中製成麴，一部分用來培養酒母，其餘投入主醪…"}},{"p":"breweries","n":1,"c":{"en":"The breweries of this book on a schematic map of Gifu's five regions.","ja":"本書に出てくる蔵を、岐阜の五つの圏域の模式図に置いたもの。","zh":"本書收錄的酒藏，標示在岐阜五大圈域的示意圖上。"}},{"p":"doburoku","n":1,"c":{"en":"One mash, three drinks, schematic.","ja":"一つの醪から三つの酒（模式図）。","zh":"同一醪，三種酒（示意圖）。"}},{"p":"doburoku","n":2,"c":{"en":"Seven ways to hold sake, schematic and not to scale.","ja":"酒を受ける七つの器（模式図・縮尺不同）。","zh":"盛酒的七種器物（示意圖，未按比例）。"}}];
